const data = $input.first().json;
const d = data.body && typeof data.body === 'object' ? data.body : data;
const text = x => typeof x === 'string' ? x.trim() : '';
return [{json: {
 nombre: text(d.nombre || d.name), email: text(d.email).toLowerCase(),
 telefono: text(d.telefono || d.phone), mensaje: text(d.mensaje || d.message).slice(0, 4000),
 origen: text(d.origen) || 'formulario web', recibido: new Date().toISOString()
}}];

