parameters.jsCode:
const ia = $input.first().json;
const consulta = $('Normalizar datos').first().json;
let salida;
try {
 const raw = JSON.parse(ia.choices[0].message.content);
 if (!raw || !['comercial','soporte','administracion','otro'].includes(raw.categoria) ||
     !['alta','media','baja'].includes(raw.urgencia) ||
     typeof raw.resumen !== 'string' || typeof raw.respuesta !== 'string') throw new Error('Formato inválido');
 salida = {categoria:raw.categoria, urgencia:raw.urgencia, resumen:raw.resumen.slice(0,400), respuesta:raw.respuesta.slice(0,1400), estado_ia:'borrador'};
} catch {
 salida = {categoria:'otro', urgencia:'media', resumen:'Revisión manual: respuesta no disponible o no válida', respuesta:'', estado_ia:'revision_manual'};
}
return [{json:{...consulta,...salida}}];

